mapper.select:
SELECT EFTL.*,eftl.IN_BANK_ACCOUNT_NAME IN_BANK_ACCOUNT_ID_N, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.apply_currency_code ) as apply_currency_code_n, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.planned_currency_code ) as planned_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FT.PAYMENT_PURPOSE' and scvb.value = EFTL.apply_purpose ) as apply_purpose_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'SYS.YES_NO' and scvb.value = EFTL.DIRECT_FLAG ) as direct_flag_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'HLS_EFT_CONFIRM_STATUS' and scvb.value = EFTL.transfer_status ) as transfer_status_n, CBA.BANK_BRANCH_NAME OUT_BANK_BRANCH_NAME, CBA.BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_ID_N, CBA.BANK_ACCOUNT_NUM OUT_BANK_ACCOUNT_NUM, LC.MAJOR_CONTRACT_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_ID_N, nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) SOURCE_DOC_NAME, HCI.DESCRIPTION CF_ITEM_DESC, ROUND((EFTL.PLANNED_DUE_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_PLANNED_DUE_AMOUNT, ROUND((EFTL.ACTUAL_PAY_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_ACTUAL_PAY_AMOUNT FROM EFT_FUND_TRANSFER_LIST EFTL LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=EFTL.CF_ITEM AND HCI.CF_TYPE=EFTL.CF_TYPE LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID= EFTL.OUT_BANK_ACCOUNT_ID LEFT JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' LEFT JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY!='LON_CONTRACT_REPAYMENT' AND EFTL.SOURCE_DOC_CATEGORY!='CT_ABS_PROJECT_FEE' LEFT JOIN CT_ABS_PROJECT CAJ ON CAJ.PROJECT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY= 'CT_ABS_PROJECT_FEE' WHERE 1=1
AND EFTL.TRANSFER_ID = #{transferId}
AND EFTL.FIN_TRANSFER_ID = #{finTransferId}
ORDER BY EFTL.APPLY_PAY_DATE

SELECT EFTL.*, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.apply_currency_code ) as apply_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FT.PAYMENT_PURPOSE' and scvb.value = EFTL.apply_purpose ) as apply_purpose_n, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.planned_currency_code ) as planned_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'HLS.WORK_FLOW_STATUS' and scvb.value = EFTL.transfer_status ) as transfer_status_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'HLS.WORK_FLOW_STATUS' and scvb.value = FT.APPLY_STATUS ) as fin_apply_status_n, CBA.BANK_BRANCH_NAME OUT_BANK_BRANCH_NAME, CBA.BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_NAME, CBA.BANK_ACCOUNT_NUM OUT_BANK_ACCOUNT_NUM, LC.MAJOR_CONTRACT_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_NUMBER, nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) SOURCE_DOC_NAME, HCI.DESCRIPTION CF_ITEM_DESC, ROUND((EFTL.PLANNED_DUE_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_PLANNED_DUE_AMOUNT, ROUND((EFTL.ACTUAL_PAY_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_ACTUAL_PAY_AMOUNT, SU.DESCRIPTION APPLY_USER_NAME, EFT.APPLY_STATUS, FT.APPLY_STATUS FIN_APPLY_STATUS FROM EFT_FUND_TRANSFER_LIST EFTL JOIN EFT_FUND_TRANSFER EFT ON EFT.TRANSFER_ID=EFTL.TRANSFER_ID JOIN SYS_USER SU ON SU.USER_ID=EFT.CREATED_BY LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=EFTL.CF_ITEM AND HCI.CF_TYPE=EFTL.CF_TYPE LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID= EFTL.OUT_BANK_ACCOUNT_ID LEFT JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' LEFT JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY!='LON_CONTRACT_REPAYMENT' AND EFTL.SOURCE_DOC_CATEGORY!='CT_ABS_PROJECT_FEE' LEFT JOIN CT_ABS_PROJECT CAJ ON CAJ.PROJECT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY= 'CT_ABS_PROJECT_FEE' LEFT JOIN EFT_FUND_TRANSFER FT ON FT.TRANSFER_ID=EFTL.FIN_TRANSFER_ID WHERE EFT.DATA_CLASS='NORMAL' AND EFTL.DATA_CLASS='NORMAL'
AND EFTL.APPLY_PAY_DATE >= #{dueDateStart}
AND EFTL.APPLY_PAY_DATE <= #{dueDateEnd}
AND EFTL.ORGANIZATION_NAME LIKE CONCAT(CONCAT('%',#{organizationName}),'%')
AND SU.DESCRIPTION LIKE CONCAT(CONCAT('%',#{applyUserName}),'%')
AND( CBA.BANK_BRANCH_NAME LIKE CONCAT(CONCAT('%',#{outBankAccountName}),'%') OR CBA.BANK_ACCOUNT_NAME LIKE CONCAT(CONCAT('%',#{outBankAccountName}),'%') OR CBA.BANK_ACCOUNT_NUM LIKE CONCAT(CONCAT('%',#{outBankAccountName}),'%') )
AND( EFTL.IN_BANK_BRANCH_NAME LIKE CONCAT(CONCAT('%',#{inBankAccountName}),'%') OR EFTL.IN_BANK_ACCOUNT_NAME LIKE CONCAT(CONCAT('%',#{inBankAccountName}),'%') OR EFTL.IN_BANK_ACCOUNT_NUM LIKE CONCAT(CONCAT('%',#{inBankAccountName}),'%') )
AND EFTL.APPLY_PAY_AMOUNT >= #{applyPayAmountStart}
AND EFTL.APPLY_PAY_AMOUNT <= #{applyPayAmountStart}
AND FT.APPLY_STATUS = #{finApplyStatus}
AND FT.APPLY_STATUS IS NULL
ORDER BY EFT.APPLY_DATE DESC

SELECT EFTL.*, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.apply_currency_code ) as apply_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FT.PAYMENT_PURPOSE' and scvb.value = EFTL.apply_purpose ) as apply_purpose_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'HLS_EFT_CONFIRM_STATUS' and scvb.value = EFTL.transfer_status ) as transfer_status_n, CBA.BANK_BRANCH_NAME OUT_BANK_BRANCH_NAME, CBA.BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_NAME, CBA.BANK_ACCOUNT_NUM OUT_BANK_ACCOUNT_NUM, LC.MAJOR_CONTRACT_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_NUMBER, nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) SOURCE_DOC_NAME, HCI.DESCRIPTION CF_ITEM_DESC, ROUND((EFTL.PLANNED_DUE_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_PLANNED_DUE_AMOUNT, ROUND((EFTL.ACTUAL_PAY_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_ACTUAL_PAY_AMOUNT FROM EFT_FUND_TRANSFER_LIST EFTL JOIN EFT_FUND_TRANSFER EFT ON EFT.TRANSFER_ID=EFTL.TRANSFER_ID LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=EFTL.CF_ITEM AND HCI.CF_TYPE=EFTL.CF_TYPE LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID= EFTL.OUT_BANK_ACCOUNT_ID LEFT JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' LEFT JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY!='LON_CONTRACT_REPAYMENT' AND EFTL.SOURCE_DOC_CATEGORY!='CT_ABS_PROJECT_FEE' LEFT JOIN CT_ABS_PROJECT CAJ ON CAJ.PROJECT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY= 'CT_ABS_PROJECT_FEE' WHERE 1=1 AND EFTL.DATA_CLASS='NORMAL' AND EFT.APPLY_STATUS='APPROVED' AND EFT.DATA_CLASS='NORMAL' AND nvl(EFTL.FIN_TRANSFER_ID,0)=0 AND EFT.COMPANY_ID = #{request.companyId}
AND EFTL.APPLY_PAY_DATE >= #{dueDateStart}
AND EFTL.APPLY_PAY_DATE <= #{dueDateEnd}
AND EFTL.APPLY_PURPOSE=#{applyPurpose}
AND EFTL.TRANSFER_STATUS=#{transferStatus}
AND 1=1
AND EFTL.TRANSFER_STATUS!='CANCEL'
AND EFTL.ORGANIZATION_NAME LIKE CONCAT(CONCAT('%',#{organizationName}),'%')
AND EFTL.TRANSFER_NUMBER LIKE CONCAT(CONCAT('%',#{transferNumber}),'%')
AND nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) LIKE CONCAT(CONCAT('%',#{sourceDocName}),'%')
AND nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) LIKE CONCAT(CONCAT('%',#{sourceDocNumber}),'%')
and ( CBA.BANK_BRANCH_NAME like CONCAT(CONCAT('%',#{outbankAccountInfo}),'%') or CBA.BANK_ACCOUNT_NAME like CONCAT(CONCAT('%',#{outbankAccountInfo}),'%') or CBA.BANK_ACCOUNT_NUM like CONCAT(CONCAT('%',#{outbankAccountInfo}),'%') )
ORDER BY EFT.APPLY_DATE DESC

SELECT EFTL.*, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.apply_currency_code ) as apply_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FT.PAYMENT_PURPOSE' and scvb.value = EFTL.apply_purpose ) as apply_purpose_n, CBA.BANK_BRANCH_NAME OUT_BANK_BRANCH_NAME, CBA.BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_NAME, CBA.BANK_ACCOUNT_NUM OUT_BANK_ACCOUNT_NUM, LC.MAJOR_CONTRACT_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_NUMBER, nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) SOURCE_DOC_NAME, HCI.DESCRIPTION CF_ITEM_DESC, ROUND((EFTL.PLANNED_DUE_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_PLANNED_DUE_AMOUNT, ROUND((EFTL.ACTUAL_PAY_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_ACTUAL_PAY_AMOUNT FROM EFT_FUND_TRANSFER_LIST EFTL JOIN EFT_FUND_TRANSFER EFT ON EFTL.TRANSFER_ID=EFT.TRANSFER_ID LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=EFTL.CF_ITEM AND HCI.CF_TYPE=EFTL.CF_TYPE LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID= EFTL.OUT_BANK_ACCOUNT_ID LEFT JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' LEFT JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY!='LON_CONTRACT_REPAYMENT' AND EFTL.SOURCE_DOC_CATEGORY!='CT_ABS_PROJECT_FEE' LEFT JOIN CT_ABS_PROJECT CAJ ON CAJ.PROJECT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY= 'CT_ABS_PROJECT_FEE' WHERE 1=1 AND EFT.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_STATUS!='CANCEL' AND EFT.COMPANY_ID = #{request.companyId}
AND EFT.BUSINESS_TYPE = #{businessType}
AND EFTL.APPLY_PURPOSE=#{applyPurpose}
AND EFTL.TRANSFER_NUMBER LIKE CONCAT(CONCAT('%',#{transferNumber}),'%')
AND EFTL.APPLY_PAY_AMOUNT =#{applyPayAmount,jdbcType=DECIMAL}
And CBA.BANK_ACCOUNT_NUM Like '%'||#{outBankAccountNum,jdbcType=VARCHAR}||'%'
And EFTL.IN_BANK_ACCOUNT_NUM Like '%'||#{inBankAccountNum,jdbcType=VARCHAR}||'%'

SELECT EFTL.*, ( select fc.currency_name from fnd_currency fc where fc.currency_code = EFTL.apply_currency_code ) as apply_currency_code_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'FT.PAYMENT_PURPOSE' and scvb.value = EFTL.apply_purpose ) as apply_purpose_n, CBA.BANK_BRANCH_NAME OUT_BANK_BRANCH_NAME, CBA.BANK_ACCOUNT_NAME OUT_BANK_ACCOUNT_NAME, CBA.BANK_ACCOUNT_NUM OUT_BANK_ACCOUNT_NUM, LC.MAJOR_CONTRACT_NUMBER, nvl(nvl(LCW.WITHDRAW_NUMBER,CAP.PRODUCT_NUMBER),CAJ.PROJECT_NUMBER) SOURCE_DOC_NUMBER, nvl(nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME),CAJ.PROJECT_SHORT_NAME) SOURCE_DOC_NAME, HCI.DESCRIPTION CF_ITEM_DESC, ROUND((EFTL.PLANNED_DUE_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_PLANNED_DUE_AMOUNT, ROUND((EFTL.ACTUAL_PAY_AMOUNT*EFTL.EXCHANGE_RATE),2) CNY_ACTUAL_PAY_AMOUNT FROM EFT_FUND_TRANSFER_LIST EFTL JOIN EFT_FUND_TRANSFER EFT ON EFTL.TRANSFER_ID=EFT.TRANSFER_ID LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=EFTL.CF_ITEM AND HCI.CF_TYPE=EFTL.CF_TYPE LEFT JOIN CSH_BANK_ACCOUNT CBA ON CBA.BANK_ACCOUNT_ID= EFTL.OUT_BANK_ACCOUNT_ID LEFT JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY='LON_CONTRACT_REPAYMENT' LEFT JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY!='LON_CONTRACT_REPAYMENT' AND EFTL.SOURCE_DOC_CATEGORY!='CT_ABS_PROJECT_FEE' LEFT JOIN CT_ABS_PROJECT CAJ ON CAJ.PROJECT_ID=EFTL.SOURCE_DOC_ID AND EFTL.SOURCE_DOC_CATEGORY= 'CT_ABS_PROJECT_FEE' WHERE 1=1 AND EFT.DATA_CLASS='NORMAL' AND EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.ACTUAL_PAY_AMOUNT=EFTL.APPLY_PAY_AMOUNT AND EFT.COMPANY_ID = #{request.companyId}
AND EFTL.APPLY_PAY_DATE >= #{dueDateStart}
AND EFTL.APPLY_PAY_DATE <= #{dueDateEnd}
AND EFTL.ORGANIZATION_NAME LIKE CONCAT(CONCAT('%',#{organizationName}),'%')
AND nvl(LC.CONTRACT_NAME,CAP.PRODUCT_SHORT_NAME) LIKE CONCAT(CONCAT('%',#{sourceDocName}),'%')
ORDER BY EFT.APPLY_DATE DESC

SELECT BALANCE.*, case when BALANCE.APPLY_PAY_AMOUNT > 0 then BALANCE.APPLY_PAY_AMOUNT else 0 end apply_receipt_amount FROM ( SELECT ACCOUNT.APPLY_PAY_AMOUNT, ACCOUNT.APPLY_PAY_DATE , ACCOUNT.IN_BANK_ACCOUNT_ID, ACCOUNT.CF_ITEM, nvl(SC.MEANING,HCI.DESCRIPTION) CF_ITEM_DESC, ACCOUNT.SOURCE_DOC_NUMBER, ACCOUNT.SOURCE_DOC_NAME, ACCOUNT.APPLY_PURPOSE FROM ( SELECT AC.IN_BANK_ACCOUNT_ID, AC.APPLY_PAY_DATE , AC.APPLY_PAY_AMOUNT, AC.CF_ITEM, AC.SOURCE_DOC_NUMBER, AC.SOURCE_DOC_NAME, AC.APPLY_PURPOSE FROM ( SELECT CPRL.SELF_BANK_ACCOUNT_ID IN_BANK_ACCOUNT_ID, CPRH.PAYMENT_REQ_DATE APPLY_PAY_DATE, -(CPRL.AMOUNT-nvl(CPRL.AMOUNT_PAID,0)) APPLY_PAY_AMOUNT, 'CON_CONTRACT' SOURCE_DOC_CATEGORY, 40 CF_ITEM, PP.APPROVAL_NUMBER SOURCE_DOC_NUMBER, CC.CONTRACT_NAME SOURCE_DOC_NAME, NULL APPLY_PURPOSE FROM CSH_PAYMENT_REQ_LN CPRL JOIN CSH_PAYMENT_REQ_HD CPRH ON CPRH.PAYMENT_REQ_ID = CPRL.PAYMENT_REQ_ID JOIN CON_CONTRACT CC ON CPRH.SOURCE_DOC_ID = CC.CONTRACT_ID AND CPRH.SOURCE_DOC_TYPE='CON_CONTRACT' JOIN PRJ_PROJECT PP ON PP.PROJECT_ID=CC.PROJECT_ID WHERE CPRL.PAYMENT_FLAG IN ('NOT', 'PARTIAL') AND CC.CONTRACT_STATUS IN ('SIGN', 'LOAN') AND CPRH.PAYMENT_REQ_STATUS='APPROVED' AND CC.DATA_CLASS='NORMAL' AND CPRL.SELF_BANK_ACCOUNT_ID IS NOT NULL UNION ALL SELECT CPRL.SELF_BANK_ACCOUNT_ID , CPRH.PAYMENT_REQ_DATE, -(CPRL.AMOUNT-nvl(CPRL.AMOUNT_PAID,0)) AMOUNT, 'FCT_CONTRACT' SOURCE_DOC_CATEGORY, 0 CF_ITEM, FC.APPROVAL_NUMBER, FC.CONTRACT_NAME, NULL APPLY_PURPOSE FROM CSH_PAYMENT_REQ_LN CPRL JOIN CSH_PAYMENT_REQ_HD CPRH ON CPRH.PAYMENT_REQ_ID = CPRL.PAYMENT_REQ_ID JOIN FCT_CONTRACT FC ON CPRH.SOURCE_DOC_ID = FC.CONTRACT_ID AND CPRH.SOURCE_DOC_TYPE='FCT_CONTRACT' WHERE FC.CONTRACT_STATUS IN ('SIGN', 'LOAN') AND CPRH.DOCUMENT_TYPE = 'PAYMENT_REQ' AND CPRL.PAYMENT_FLAG IN ('NOT', 'PARTIAL') AND CPRH.PAYMENT_REQ_STATUS='APPROVED' AND CPRL.SELF_BANK_ACCOUNT_ID IS NOT NULL UNION ALL SELECT CC.RETURN_ACCOUNT, CCC.DUE_DATE, (CCC.DUE_AMOUNT-nvl(CCC.RECEIVED_AMOUNT,0)) AMOUNT, 'CON_CONTRACT' SOURCE_DOC_CATEGORY, CCC.CF_ITEM, PP.APPROVAL_NUMBER, CC.CONTRACT_NAME, NULL APPLY_PURPOSE FROM CON_CONTRACT CC JOIN CON_CONTRACT_CASHFLOW CCC ON CC.CONTRACT_ID=CCC.CONTRACT_ID JOIN PRJ_PROJECT PP ON PP.PROJECT_ID=CC.PROJECT_ID WHERE CCC.CF_DIRECTION='INFLOW' AND nvl(CCC.WRITE_OFF_FLAG,'NOT') !='FULL' AND CC.DATA_CLASS = 'NORMAL' AND CCC.CF_STATUS = 'RELEASE' AND CC.RETURN_ACCOUNT IS NOT NULL AND (( CC.CONTRACT_STATUS='INCEPT') OR ( CCC.TIMES=0 AND CC.CONTRACT_STATUS IN('SIGN', 'LOAN')) OR ( CC.CONTRACT_STATUS='PENDING' AND ( ( SELECT COUNT(1) FROM CON_CONTRACT FT WHERE FT.DATA_CLASS='CHANGE_REQ' AND FT.CONTRACT_STATUS='INCEPT' AND FT.REF_CONTRACT_ID=CC.CONTRACT_ID ) >0))) UNION ALL SELECT FC.FCT_PAYMENT_ACCOUNT_ID, FQC.DUE_DATE, (FQC.DUE_AMOUNT-nvl(FQC.RECEIVED_AMOUNT,0)) AMOUNT, 'FCT_CONTRACT' SOURCE_DOC_CATEGORY, FQC.CF_ITEM, FC.APPROVAL_NUMBER, FC.CONTRACT_NAME, NULL APPLY_PURPOSE FROM FCT_CONTRACT FC JOIN FCT_QUOTATION_CASHFLOW FQC ON FC.CONTRACT_ID=FQC.CONTRACT_ID WHERE FQC.CF_DIRECTION='INFLOW' AND nvl(FQC.WRITE_OFF_FLAG,'NOT') !='FULL' AND FC.DATA_CLASS = 'NORMAL' AND FQC.CF_STATUS = 'RELEASE' AND FC.FCT_PAYMENT_ACCOUNT_ID IS NOT NULL AND (( FC.CONTRACT_STATUS='INCEPT') OR ( FQC.TIMES=0 AND FC.CONTRACT_STATUS IN('SIGN', 'LOAN')) OR ( FC.CONTRACT_STATUS='PENDING' AND ( ( SELECT COUNT(1) FROM FCT_CONTRACT FT WHERE FT.DATA_CLASS='CHANGE_REQ' AND FT.CONTRACT_STATUS='INCEPT' AND FT.REF_CONTRACT_ID=FC.CONTRACT_ID ) >0))) UNION ALL SELECT TEMP.* FROM ( SELECT CASE WHEN LCR.CF_ITEM=301 THEN BAPRI.BANK_ACCOUNT_ID WHEN LCR.CF_ITEM=302 THEN BAINT.BANK_ACCOUNT_ID WHEN LCR.CF_ITEM=310 THEN BAFEE.BANK_ACCOUNT_ID END BANK_ACCOUNT_ID, LCR.PLANNED_DUE_DATE, -ROUND(LCR.PLANNED_DUE_AMOUNT*nvl(LCR.EXCHANGE_RATE,1),2)-ifnull (LCR.CNY_DUE_AMOUNT,0) AMOUNT, 'LON_CONTRACT' SOURCE_DOC_CATEGORY, LCR.CF_ITEM, CASE WHEN LC.MAJOR_CONTRACT_NUMBER IS NULL THEN LC.CONTRACT_NUMBER ELSE LC.MAJOR_CONTRACT_NUMBER || ' / ' || LC.CONTRACT_NUMBER END CONTRACT_NUMBER, LC.CONTRACT_NAME, NULL APPLY_PURPOSE FROM LON_CONTRACT_REPAYMENT LCR JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.WITHDRAW_ID=LCR.WITHDRAW_ID JOIN LON_CONTRACT LC ON LC.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN ( SELECT CLCBA.BANK_ACCOUNT_ID, CLCBA.CONTRACT_ID FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA WHERE CLCBA.BANK_ACCOUNT_TYPE='FINANCING_ACCOUNT' AND CLCBA.ACCOUNT_SOURCE='OUR_ACCOUNT' ) BAPRI ON BAPRI.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN ( SELECT CLCBA.BANK_ACCOUNT_ID, CLCBA.CONTRACT_ID FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA WHERE CLCBA.BANK_ACCOUNT_TYPE='FINANCING_INTEREST_ACCOUNT' AND CLCBA.ACCOUNT_SOURCE='OUR_ACCOUNT') BAINT ON BAINT.CONTRACT_ID=LCW.CONTRACT_ID LEFT JOIN ( SELECT CLCBA.BANK_ACCOUNT_ID, CLCBA.CONTRACT_ID FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA WHERE CLCBA.BANK_ACCOUNT_TYPE='FINANCING_EXPENSE_ACCOUNT' AND CLCBA.ACCOUNT_SOURCE='OUR_ACCOUNT' ) BAFEE ON BAFEE.CONTRACT_ID=LCW.CONTRACT_ID WHERE LCW.DATA_CLASS='NORMAL' AND LCW.WITHDRAW_STATUS IN('APPROVED', 'PENDING') AND nvl(LCR.WRITE_OFF_FLAG,'NOT')!='FULL') TEMP WHERE TEMP.BANK_ACCOUNT_ID IS NOT NULL UNION ALL SELECT TEMP.* FROM ( SELECT CASE CAPR.CF_ITEM WHEN 301 THEN BAPRI.BANK_ACCOUNT_ID WHEN 302 THEN BAINT.BANK_ACCOUNT_ID WHEN 201 THEN REGA.BANK_ACCOUNT_ID WHEN 202 THEN REGA.BANK_ACCOUNT_ID END BANK_ACCOUNT_ID, CAPR.PLANNED_DUE_DATE, CAPR.AMOUNT, 'ABS_PRODUCT' SOURCE_DOC_CATEGORY, CAPR.CF_ITEM, CAP.PRODUCT_NUMBER, CAP.PRODUCT_SHORT_NAME, NULL APPLY_PURPOSE FROM ( SELECT LAPR.PRODUCT_ID, LAPR.CF_ITEM, LAPR.PLANNED_DUE_DATE, -ROUND(LAPR.PLANNED_DUE_AMOUNT*nvl(LAPR.EXCHANGE_RATE,1 ),2)-ifnull (LAPR.CNY_DUE_AMOUNT,0) AMOUNT FROM CT_ABS_PRODUCT_REPAYMENT LAPR WHERE nvl(LAPR.WRITE_OFF_FLAG,'NOT')!='FULL' UNION ALL SELECT CAPC.PRODUCT_ID, CAPC.COLLECTION_CF_ITEM CF_ITEM, CAPC.COLLECTION_DATE, CAPC.COLLECTION_AMOUNT-ifnull (CAPC.COLLECTION_RECEIVER_AMOUNT,0) AMOUNT FROM CT_ABS_PRODUCT_COLLECTION CAPC WHERE CAPC.DATA_CLASS='NORMAL' AND CAPC.COLLECTION_AMOUNT-ifnull (CAPC.COLLECTION_RECEIVER_AMOUNT,0)>0 UNION ALL SELECT CAPC.PRODUCT_ID, CAPC.REMITTANCE_CF_ITEM CF_ITEM, CAPC.REMITTANCE_DATE, -(CAPC.REMITTANCE_AMOUNT-ifnull (CAPC.REMITTANCE_RECEIVER_AMOUNT,0) ) AMOUNT FROM CT_ABS_PRODUCT_COLLECTION CAPC WHERE CAPC.DATA_CLASS='NORMAL' AND CAPC.REMITTANCE_AMOUNT-ifnull (CAPC.REMITTANCE_RECEIVER_AMOUNT,0)>0 ) CAPR JOIN CT_ABS_PRODUCT CAP ON CAP.PRODUCT_ID=CAPR.PRODUCT_ID LEFT JOIN ( SELECT CABA.ABS_BANK_ACCOUNT_ID, CABA.BANK_ACCOUNT_ID, CABA.SOURCE_KEY FROM CT_ABS_BANK_ACCOUNT CABA WHERE CABA.SOURCE_TYPE='ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE='PRINCIPAL_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE='OUR_ACCOUNT') BAPRI ON BAPRI.SOURCE_KEY=CAP.PRODUCT_ID LEFT JOIN ( SELECT CABA.ABS_BANK_ACCOUNT_ID, CABA.BANK_ACCOUNT_ID, CABA.SOURCE_KEY FROM CT_ABS_BANK_ACCOUNT CABA WHERE CABA.SOURCE_TYPE='ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE='INTEREST_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE='OUR_ACCOUNT') BAINT ON BAINT.SOURCE_KEY=CAP.PRODUCT_ID LEFT JOIN ( SELECT CABA.ABS_BANK_ACCOUNT_ID, CABA.BANK_ACCOUNT_ID, CABA.SOURCE_KEY FROM CT_ABS_BANK_ACCOUNT CABA WHERE CABA.SOURCE_TYPE='ABS_PRODUCT' AND CABA.BANK_ACCOUNT_TYPE='REGULATORY_ACCOUNT' AND CABA.ACCOUNT_SOURCE_TYPE='OUR_ACCOUNT') REGA ON REGA.SOURCE_KEY=CAP.PRODUCT_ID WHERE CAP.PRODUCT_STATUS IN ('APPROVED' , 'PENDING') AND CAP.DATA_CLASS='NORMAL') TEMP WHERE TEMP.BANK_ACCOUNT_ID IS NOT NULL UNION ALL SELECT EFTL.OUT_BANK_ACCOUNT_ID, EFTL.APPLY_PAY_DATE, - EFTL.APPLY_PAY_AMOUNT, 'EFT_FUND_TRANSFER_LIST' SOURCE_DOC_CATEGORY, EFTL.CF_ITEM, EFTL.TRANSFER_NUMBER, NULL SOURCE_DOC_NAME, EFTL.APPLY_PURPOSE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS='NEW' AND EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='TRANSFER' AND nvl(EFTL.APPLY_PAY_AMOUNT,0)!=0 AND EFTL.OUT_BANK_ACCOUNT_ID IS NOT NULL UNION ALL SELECT EFTL.IN_BANK_ACCOUNT_ID, EFTL.APPLY_PAY_DATE, EFTL.APPLY_PAY_AMOUNT, 'EFT_FUND_TRANSFER_LIST' SOURCE_DOC_CATEGORY, EFTL.CF_ITEM, EFTL.TRANSFER_NUMBER, NULL SOURCE_DOC_NAME, EFTL.APPLY_PURPOSE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.TRANSFER_STATUS='NEW' AND EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='TRANSFER' AND nvl(EFTL.APPLY_PAY_AMOUNT,0)!=0 AND EFTL.IN_BANK_ACCOUNT_ID IS NOT NULL) AC WHERE 1=1 AND AC.APPLY_PAY_DATE >= sysdate
AND AC.APPLY_PAY_DATE <= #{dueDateEnd}
) ACCOUNT LEFT JOIN HLS_CASHFLOW_ITEM HCI ON HCI.CF_ITEM=ACCOUNT.CF_ITEM LEFT JOIN SC ON SC.CODE_VALUE = ACCOUNT.APPLY_PURPOSE AND SC.CODE ='FT.PAYMENT_PURPOSE' LEFT JOIN ( SELECT BANK_ACCOUNT_ID, BALANCE_DATE, ACCOUNT_BALANCE FROM ( SELECT -- ROW_NUMBER() OVER(PARTITION BY AB.BANK_ACCOUNT_ID ORDER BY -- AB.BALANCE_DATE DESC) RN, IF ( @p = AB.BANK_ACCOUNT_ID, @rank := @rank + 1 ,@rank := 1 ) AS RN, @p := AB.BANK_ACCOUNT_ID as rank1, AB.BANK_ACCOUNT_ID, AB.BALANCE_DATE, AB.ACCOUNT_BALANCE FROM CAP_ACCOUNT_MONTHLY_BALANCE AB,(SELECT @p := NULL ,@rank := 0) r) WHERE RN = 1) CBAB ON CBAB.BANK_ACCOUNT_ID=ACCOUNT.IN_BANK_ACCOUNT_ID ) BALANCE WHERE 1=1
AND BALANCE.IN_BANK_ACCOUNT_ID = #{bankAccountId}
ORDER BY BALANCE.APPLY_PAY_DATE

SELECT
    COUNT(1)
  FROM
     EFT_FUND_TRANSFER_LIST EFTL
  WHERE
      EFTL.SOURCE_DOC_CATEGORY=#{sourceDocCategory}

  AND EFTL.SOURCE_DOC_LINE_ID=#{sourceDocLineId}


  AND EFTL.SOURCE_DOC_ID=#{sourceDocId}

  AND EFTL.TRANSFER_STATUS!='CANCEL'
  AND EFTL.TRANSFER_STATUS!='CONFIRM'

SELECT TEMP.*, SCVB.MEANING WRITE_OFF_DESC FROM (
SELECT LCR.REPAYMENT_ID SOURCE_DOC_LINE_ID, LCR.TIMES, LCR.CF_ITEM, LCR.CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, LCR.PLANNED_DUE_DATE, LCR.PLANNED_DUE_AMOUNT, LCR.DUE_DATE ACTUAL_PAY_DATE, nvl(LCR.WRITE_OFF_AMOUNT,0) WRITE_OFF_AMOUNT, LCR.WRITE_OFF_FLAG FROM LON_CONTRACT_REPAYMENT LCR JOIN HLS_CASHFLOW_ITEM HCI ON LCR.CF_ITEM=HCI.CF_ITEM AND LCR.CF_TYPE=HCI.CF_TYPE WHERE LCR.WITHDRAW_ID=#{sourceDocId}
SELECT CAPR.REPAYMENT_ID SOURCE_DOC_LINE_ID, CAPR.TIMES, CAPR.CF_ITEM, CAPR.CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPR.PLANNED_DUE_DATE, CAPR.PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPR.WRITE_OFF_AMOUNT,0) WRITE_OFF_AMOUNT, CAPR.WRITE_OFF_FLAG FROM CT_ABS_PRODUCT_REPAYMENT CAPR LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PRODUCT_REPAYMENT' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPR.REPAYMENT_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPR.CF_ITEM=HCI.CF_ITEM AND CAPR.CF_TYPE=HCI.CF_TYPE WHERE CAPR.PRODUCT_ID=#{sourceDocId}
SELECT CAPC.COLLECTION_ID SOURCE_DOC_LINE_ID, CAPC.TIMES, CAPC.COLLECTION_CF_ITEM CF_ITEM, CAPC.COLLECTION_CF_TYPE CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPC.COLLECTION_DATE PLANNED_DUE_DATE, CAPC.COLLECTION_AMOUNT PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPC.COLLECTION_RECEIVER_AMOUNT,0) WRITE_OFF_AMOUNT, CASE WHEN nvl(CAPC.COLLECTION_RECEIVER_AMOUNT,0)=0 THEN 'NOT' WHEN nvl(CAPC.COLLECTION_RECEIVER_AMOUNT,0)=nvl(CAPC.COLLECTION_AMOUNT,0) THEN 'FULL' ELSE 'PARTIAL' END WRITE_OFF_FLAG FROM CT_ABS_PRODUCT_COLLECTION CAPC LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PRODUCT_COLLECTION' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPC.COLLECTION_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPC.COLLECTION_CF_ITEM=HCI.CF_ITEM AND CAPC.COLLECTION_CF_TYPE=HCI.CF_TYPE WHERE CAPC.PRODUCT_ID=#{sourceDocId} AND CAPC.DATA_CLASS='NORMAL'
SELECT CAPC.COLLECTION_ID SOURCE_DOC_LINE_ID, CAPC.TIMES, CAPC.REMITTANCE_CF_ITEM CF_ITEM, CAPC.REMITTANCE_CF_TYPE CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPC.REMITTANCE_DATE PLANNED_DUE_DATE, CAPC.REMITTANCE_AMOUNT PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPC.REMITTANCE_RECEIVER_AMOUNT,0) WRITE_OFF_AMOUNT, CASE WHEN nvl(CAPC.REMITTANCE_RECEIVER_AMOUNT,0)=0 THEN 'NOT' WHEN nvl(CAPC.REMITTANCE_RECEIVER_AMOUNT,0)=nvl(CAPC.REMITTANCE_AMOUNT,0) THEN 'FULL' ELSE 'PARTIAL' END WRITE_OFF_FLAG FROM CT_ABS_PRODUCT_COLLECTION CAPC LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PRODUCT_REMITTANCE' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPC.COLLECTION_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPC.REMITTANCE_CF_ITEM=HCI.CF_ITEM AND CAPC.REMITTANCE_CF_TYPE=HCI.CF_TYPE WHERE CAPC.PRODUCT_ID=#{sourceDocId} AND CAPC.DATA_CLASS='NORMAL'
SELECT CAPFI.FEE_INFO_ID SOURCE_DOC_LINE_ID, CAPFI.TIMES, CAPFI.CF_ITEM, CAPFI.CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPFI.PLAN_PAY_DATE PLANNED_DUE_DATE, CAPFI.FEE_AMOUNT PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPFI.WRITE_OFF_AMOUNT,0) WRITE_OFF_AMOUNT, CASE WHEN nvl(CAPFI.WRITE_OFF_AMOUNT,0)=0 THEN 'NOT' WHEN nvl(CAPFI.WRITE_OFF_AMOUNT,0)=nvl(CAPFI.FEE_AMOUNT,0) THEN 'FULL' ELSE 'PARTIAL' END WRITE_OFF_FLAG FROM CT_ABS_PRO_FEE_INFO CAPFI LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PRODUCT_FEE' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPFI.FEE_INFO_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPFI.CF_ITEM=HCI.CF_ITEM AND CAPFI.CF_TYPE=HCI.CF_TYPE WHERE CAPFI.SOURCE_TYPE='ABS_PRODUCT' AND CAPFI.SOURCE_KEY=#{sourceDocId} AND CAPFI.CALCULATE_FLAG='N'
SELECT CAPFI.FEE_INFO_ID SOURCE_DOC_LINE_ID, CAPFI.TIMES, CAPFI.CF_ITEM, CAPFI.CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPFI.PLAN_PAY_DATE PLANNED_DUE_DATE, CAPFI.FEE_AMOUNT PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPFI.WRITE_OFF_AMOUNT,0) WRITE_OFF_AMOUNT, CASE WHEN nvl(CAPFI.WRITE_OFF_AMOUNT,0)=0 THEN 'NOT' WHEN nvl(CAPFI.WRITE_OFF_AMOUNT,0)=nvl(CAPFI.FEE_AMOUNT,0) THEN 'FULL' ELSE 'PARTIAL' END WRITE_OFF_FLAG FROM CT_ABS_PRO_FEE_INFO CAPFI LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PROJECT_FEE' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPFI.FEE_INFO_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPFI.CF_ITEM=HCI.CF_ITEM AND CAPFI.CF_TYPE=HCI.CF_TYPE WHERE CAPFI.SOURCE_TYPE='ABS_PROJECT' AND CAPFI.SOURCE_KEY=#{sourceDocId}
SELECT CAPB.BUYBACK_ID SOURCE_DOC_LINE_ID, NULL TIMES, CAPB.CF_ITEM, CAPB.CF_TYPE, HCI.DESCRIPTION CF_ITEM_DESC, CAPB.BUYBACK_DATE PLANNED_DUE_DATE, CAPB.BUYBACK_AMOUNT PLANNED_DUE_AMOUNT, EFT.ACTUAL_PAY_DATE, nvl(CAPB.RECEIVER_AMOUNT,0) WRITE_OFF_AMOUNT, CASE WHEN nvl(CAPB.RECEIVER_AMOUNT,0)=0 THEN 'NOT' WHEN nvl(CAPB.RECEIVER_AMOUNT,0)=nvl(CAPB.BUYBACK_AMOUNT,0) THEN 'FULL' ELSE 'PARTIAL' END WRITE_OFF_FLAG FROM CT_ABS_PRODUCT_BUYBACK CAPB LEFT JOIN ( SELECT EFTL.SOURCE_DOC_LINE_ID, MAX(EFTL.ACTUAL_PAY_DATE) ACTUAL_PAY_DATE FROM EFT_FUND_TRANSFER_LIST EFTL WHERE EFTL.DATA_CLASS='NORMAL' AND EFTL.TRANSFER_TYPE='PAY' AND EFTL.TRANSFER_STATUS='CONFIRM' AND EFTL.SOURCE_DOC_CATEGORY='CT_ABS_PRODUCT_BUYBACK' GROUP BY EFTL.SOURCE_DOC_LINE_ID ) EFT ON EFT.SOURCE_DOC_LINE_ID=CAPB.BUYBACK_ID JOIN HLS_CASHFLOW_ITEM HCI ON CAPB.CF_ITEM=HCI.CF_ITEM AND CAPB.CF_TYPE=HCI.CF_TYPE WHERE CAPB.PRODUCT_ID=#{sourceDocId}
) TEMP JOIN SYS_CODE_VALUE_B SCVB ON SCVB.VALUE=TEMP.WRITE_OFF_FLAG JOIN SYS_CODE_B SCB ON SCB.CODE_ID=SCVB.CODE_ID AND SCB.CODE='CSH.WRITE_OFF_FLAG' WHERE 1=1 ORDER BY TEMP.CF_ITEM, TEMP.TIMES,TEMP.PLANNED_DUE_DATE

SELECT DISTINCT ACCOUNT_SOURCE FROM CT_LON_CONTRACT_BANK_ACCOUNT CLCBA
INNER  JOIN LON_CONTRACT_WITHDRAW LCW on CLCBA.CONTRACT_ID = LCW.CONTRACT_ID
WHERE LCW.WITHDRAW_ID= #{sourceDocId,jdbcType=BIGINT}
AND CLCBA.BANK_ACCOUNT_TYPE= #{cfItem,jdbcType=VARCHAR}

select * from EFT_FUND_TRANSFER_LIST EFTL
where 1=1

    AND EFTL.TRANSFER_ID = #{transferId}


    AND EFTL.FIN_TRANSFER_ID = #{finTransferId}

ORDER BY EFTL.APPLY_PAY_DATE

select eftl.TRANSFER_LIST_ID, eftl.OUT_BANK_ACCOUNT_ID, (select cb.bank_name from csh_bank_account c1,csh_bank cb where c1.enabled_flag = 'Y' and c1.bank_id = cb.bank_id and c1.bank_account_id = eftl.OUT_BANK_ACCOUNT_ID) out_bank_account_id_n, (select c1.bank_account_num from csh_bank_account c1 where c1.bank_account_id = eftl.OUT_BANK_ACCOUNT_ID) PAYMENT_ACCOUNT, eftl.payment_amount , eftl.SOURCE_DOC_LINE_ID , (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = ln.BP_ID) source_doc_line_id_n, hba.bank_account_id, eftl.IN_BANK_ACCOUNT_NAME, eftl.IN_BANK_ACCOUNT_NUM, eftl.IN_BANK_BRANCH_NAME, ccc.payment_method, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'CSH.PAYMENT_METHOD' and scb.code_id = scvb.code_id and scvb.value = ccc.payment_method ) payment_method_n, (select t.company_full_name from fnd_company t ,prj_project pp where t.company_id=pp.company_spv and pp.project_id = cc.project_id) PAYMENT_NAME, eftl.description, (SELECT currency_name FROM fnd_currency where currency_code = ln.currency) currency_n, ln.EXCHANGE from EFT_FUND_TRANSFER_LIST eftl left join csh_payment_req_ln ln on eftl.SOURCE_DOC_LINE_ID = ln.payment_req_ln_id left join con_contract_cashflow ccc on ccc.cashflow_id = ln.SOURCE_DOC_LINE_ID left join hls_bp_master_bank_account hba on hba.bank_account_id = ccc.bank_account_id , csh_payment_req_hd hd,con_contract cc
eftl.SOURCE_DOC_ID = hd.PAYMENT_REQ_ID and cc.contract_id = ccc.contract_id
AND EFTL.SOURCE_DOC_ID = #{paymentReqId}
AND EFTL.SOURCE_DOC_ID = #{sourceDocId}
ORDER BY EFTL.APPLY_PAY_DATE
